// ====== ZENTRALE CONFIG ======
// Hier alle IDs / Steuersätze pflegen.
// -> priceListId je Land AT / CH aus Shopify Admin (Markets -> Preisliste) eintragen.
// -> collectionId für "Bücher" und "Merch" eintragen (GID-Format: gid://shopify/Collection/1234567890).

const config = {
  shop: 'vdzvc0-nd',
  apiVersion: '2024-10',

  // Collections zur Unterscheidung Buch vs. Merch
  collectionBuecher: 'gid://shopify/Collection/311681220723',
  collectionMerch:   'gid://shopify/Collection/313480249459',
  collectionBundles: 'gid://shopify/Collection/320880640115',

  // Steuersätze (Dezimal). DE = Basis der Bruttopreise im DE-Katalog.
  tax: {
    DE: { buch: 0.07,  merch: 0.19 },
    AT: { buch: 0.10,  merch: 0.20 },
    CH: { buch: 0.026, merch: 0.081 }
  },

  // Zielpreislisten (Markets). IDs eintragen.
  priceLists: {
    AT: { id: 'gid://shopify/PriceList/18960056435', currency: 'EUR' },
    CH: { id: 'gid://shopify/PriceList/18959958131', currency: 'EUR' }
  }
};

// staticData vorbereiten / leeren
const staticData = $getWorkflowStaticData('global');
staticData.produkte = [];

// Start-Cursor null => erste Seite
return [{
  json: {
    accessToken: $('Token holen ').item.json.access_token,
    cursor: null,
    hasNext: true,
    config: config
  }
}];

parameters.jsonBody:
={{ JSON.stringify({ query: `query($cursor: String, $cBuch: ID!, $cMerch: ID!, $cBundle: ID!) {
  products(first: 100, after: $cursor) {
    pageInfo { hasNextPage endCursor }
    edges {
      node {
        id
        title
        inBuecher: inCollection(id: $cBuch)
        inMerch: inCollection(id: $cMerch)
        inBundle: inCollection(id: $cBundle)
        variants(first: 100) {
          edges { node { id price sku } }
        }
      }
    }
  }
}`, variables: { cursor: $json.cursor, cBuch: $json.config.collectionBuecher, cMerch: $json.config.collectionMerch, cBundle: $json.config.collectionBundles } }) }}

